ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *ScopeOp;
    ACPI_PARSE_OBJECT *Next;

    /* Check if there is a current Op */
    if (!Op) {
        return (AE_BAD_PARAMETER);
    }

    /* Determine the scope Op */
    ScopeOp = Op->Common.Parent;

    while (ScopeOp && ScopeOp->Common.Class == ACPI_CLASS_CONTROL) {
        ScopeOp = ScopeOp->Common.Parent;
    }

    if (!ScopeOp) {
        return (AE_BAD_PARAMETER);
    }

    /* Execute any ascending callbacks */
    if (WalkState->DescendingCallback && WalkState->AscendingCallback) {
        Status = WalkState->AscendingCallback(WalkState, Op, NULL);
        if (ACPI_FAILURE(Status)) {
            return (Status);
        }
    }

    /* Process Op completion logic */
    if (Op->Named.Next) {
        Next = Op->Named.Next;
        Op->Named.Next = NULL;
        if (Next) {
            Status = AcpiPsCompleteFinalOp(WalkState, Next, Status);
            if (ACPI_FAILURE(Status)) {
                return (Status);
            }
        }
    }

    /* Manage the scope stack */
    if (WalkState->ScopeDepth > 0) {
        WalkState->ScopeDepth--;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *PrevOp;
    ACPI_PARSE_OBJECT *ParentOp;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    PrevOp = Op->Common.Next;
    ParentOp = Op->Common.Parent;

    if (PrevOp && (PrevOp != ParentOp)) {
        PrevOp->Common.Next = Op->Common.Next;
    }

    if (ParentOp) {
        ParentOp->Common.Value.Arg = Op->Common.Value.Arg;
    }

    if (Status == AE_CTRL_TRANSFER_FATAL) {
        WalkState->ControlState = Status;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *ParentOp;
    ACPI_STATUS Status2;

    /* Check if this Op is part of a scope (e.g., IF, WHILE, etc.) */
    if (Op->Common.Value.Type & (ACPI_TYPE_LOCAL_REFERENCE | ACPI_TYPE_REGION)) {
        /* Handle any ascending callbacks if needed */
        if (WalkState->MethodNode && WalkState->ParserState.ScopeInfo) {
            Status2 = AcpiPsExitScope(WalkState, Op);
            if (ACPI_FAILURE(Status2)) {
                return (Status2);
            }
        }

        /* Remove the Op from the scope stack */
        ParentOp = Op->Common.Parent;
        if (ParentOp && (ParentOp->Common.Value.Type == ACPI_TYPE_METHOD)) {
            Op->Common.Parent = NULL;
        }
    }

    /* Update the status if necessary */
    if (ACPI_FAILURE(Status)) {
        return (Status);
    }

    return (AE_OK);
}

ACPI_STATUS AcpiPsCompleteLastOperation(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *ParentOp;
    ACPI_STATUS Status2;

    if (!WalkState || !Op) {
        return (AE_BAD_PARAMETER);
    }

    if (WalkState->ScopeDepth > 0) {
        WalkState->ScopeDepth--;

        if (WalkState->Scope[WalkState->ScopeDepth].NumOperands > 0) {
            WalkState->Scope[WalkState->ScopeDepth].NumOperands--;
        }
    }

    if (Op->Common.Value.Arg) {
        AcpiUtDeleteObjectDesc(Op->Common.Value.Arg);
    }

    ParentOp = Op->Common.Parent;
    if (ParentOp && ParentOp->Common.Type == AML_PACKAGE_OP) {
        if (ParentOp->Package.PackageObj.NumElements < ParentOp->Package.PackageObj.MaxElements) {
            ParentOp->Package.PackageObj.NumElements++;
        }
    }

    if (WalkState->DescendingCallback) {
        Status2 = WalkState->DescendingCallback(WalkState, Op, NULL);
        if (Status2 != AE_OK) {
            Status = Status2;
        }
    }

    return (Status);
}

ACPI_STATUS CompleteAcpiParseOperation(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_STATUS Result = Status;

    if (WalkState && Op) {
        while (Op) {
            if (Op->Common.Value.Arg) {
                ACPI_FREE(Op->Common.Value.Arg);
            }

            if (Op->Common.Node) {
                ACPI_OBJECT_NAME OpName;
                ACPI_GET_NAME(Op->Common.Node, OpName);
                if (Result == AE_OK) {
                    Result = WalkState->DescBase->Methods->DescendingCallback(WalkState, OpName, Op->Common.Node);
                }
            }

            Op = Op->Common.Parent;
        }

        if (WalkState->Scope.Count > 0) {
            WalkState->Scope.Count--;
        }
    }

    return Result;
}
